import os
import json
import asyncio
import aiohttp

TRANSPILE_SYSTEM_PROMPT = """You are a Zig-to-Lean 4 formal verification transpiler. Output MUST be ONLY raw, valid Lean 4 code—absolutely no surrounding text, no markdown fences, no comments, no explanations. STRICTLY FORBIDDEN: axiom, sorry, admit, {!!}, ProofWanted, undefined, unfinished, ellipses, or any placeholder. Every single theorem and lemma must end with a complete, valid by proof block terminating in done; decompose complex proofs into sub-lemmas and explicit tactic steps until trivial. Implement the entire Zig logic as precise definitions, state all structural invariants and correctness properties as theorems, and prove every one with exhaustive, machine-checkable detail. The ratio of proof lines to definition lines must be at least 2:1. Use only Mathlib imports; represent fixed-size arrays as Vector, mark recursive functions as partial only when necessary. The output must begin with the first character of the first import and end with the final character of the last proof. 2026 context windows support 64k–2M tokens—output the complete, unabridged, production-ready verification file without abbreviation. You are an expert Zig-to-Lean 4 formal verification engine. Your task is to transpile the provided Zig code into a single, comprehensive, valid Lean 4 source file. OUTPUT REQUIREMENTS (NON-NEGOTIABLE): Format: Output only raw Lean 4 code. Do not include markdown fences (
lean:disable-run Completeness: The output must be the full, unabridged source. You must implement 100% of the logic, state 100% of the invariants, and write 100% of the proofs.No Placeholders: It is strictly forbidden to use sorry, admit, axiom, variable, ProofWanted, ..., {!!}, or any other placeholder. Every proof must be closed with done or qed via valid tactics.No Comments: Do not write comments in the code. Do not preserve original comments.Verification Standard:Define all Zig structures and logic using Mathlib types (Vector, Finset, RBMap).For every major function, define a corresponding theorem stating its correctness or invariant preservation(e.g.,bounds_check,conservation_of_mass).Provide the full by ... tactic block for every theorem.Length: The output should be approximately 3-5x the length of the input due to the verbosity of formal proofs.Recursion: Use partial def only if strictly necessary; prefer well-founded recursion with termination_by to ensure total functions.STRICT PROHIBITION:If you output a partial file, a summary, or code containing sorry, you fail. You must generate the full 60k+ token output if necessary.BEGIN LEAN 4 CODE:"""

CONCURRENCY = 10
MAX_RETRIES = 3
BASE_DELAY = 2

rate_limit_lock = asyncio.Lock()
last_rate_limit_time = [0]


def normalize_messages(messages):
    normalized = []
    for message in messages:
        role = str(message.get("role", "user")).strip() or "user"
        content = message.get("content", "")
        if isinstance(content, str):
            normalized.append({
                "role": role,
                "content": [{
                    "type": "text",
                    "text": content
                }]
            })
        elif isinstance(content, list):
            parts = []
            for item in content:
                if isinstance(
                        item,
                        dict) and item.get("type") == "text" and isinstance(
                            item.get("text"), str):
                    parts.append({"type": "text", "text": item["text"]})
                elif isinstance(item, str):
                    parts.append({"type": "text", "text": item})
            if not parts:
                parts.append({"type": "text", "text": ""})
            normalized.append({"role": role, "content": parts})
        else:
            normalized.append({
                "role":
                role,
                "content": [{
                    "type": "text",
                    "text": str(content)
                }]
            })
    return normalized


async def invoke_bedrock_async(session,
                               messages,
                               system=None,
                               max_tokens=64000,
                               temperature=0.0,
                               region=None,
                               model_id=None,
                               api_key=None):
    if not api_key:
        return {
            "ok": False,
            "error": {
                "message": "Missing AWS_BEARER_TOKEN_BEDROCK"
            }
        }
    if not region:
        region = "us-east-1"
    if not model_id:
        model_id = "anthropic.claude-opus-4-6-v1"

    url = f""

    body = {
        "anthropic_version": "bedrock-2023-05-31",
        "max_tokens": int(max_tokens),
        "messages": normalize_messages(messages)
    }
    if system:
        body["system"] = system
    if temperature is not None:
        body["temperature"] = float(temperature)

    headers = {
        "Content-Type": "application/json",
        "Accept": "application/json",
        "Authorization": f"Bearer {api_key}",
        "x-amz-bedrock-api-version": "2023-10-01"
    }

    for attempt in range(MAX_RETRIES):
        try:
            async with session.post(
                    url,
                    json=body,
                    headers=headers,
                    timeout=aiohttp.ClientTimeout(total=600)) as response:
                status = response.status
                raw_bytes = await response.read()

                if status == 429 or "Too many requests" in raw_bytes.decode(
                        "utf-8", errors="ignore"):
                    async with rate_limit_lock:
                        import time
                        now = time.time()
                        if now - last_rate_limit_time[0] > 1:
                            last_rate_limit_time[0] = now
                            delay = BASE_DELAY * (attempt + 1)
                            await asyncio.sleep(delay)
                    continue

                if status >= 500:
                    await asyncio.sleep(BASE_DELAY)
                    continue

                if status != 200:
                    try:
                        error_body = json.loads(raw_bytes.decode("utf-8"))
                    except:
                        error_body = {
                            "message": raw_bytes.decode("utf-8",
                                                        errors="ignore")
                        }
                    return {"ok": False, "status": status, "error": error_body}

                try:
                    parsed = json.loads(raw_bytes.decode("utf-8"))
                    return {"ok": True, "data": parsed}
                except:
                    return {
                        "ok": True,
                        "data": {
                            "raw": raw_bytes.decode("utf-8", errors="ignore")
                        }
                    }
        except asyncio.TimeoutError:
            if attempt < MAX_RETRIES - 1:
                await asyncio.sleep(BASE_DELAY)
                continue
            return {"ok": False, "error": {"message": "Timeout"}}
        except Exception as e:
            if attempt < MAX_RETRIES - 1:
                await asyncio.sleep(BASE_DELAY)
                continue
            return {"ok": False, "error": {"message": str(e)}}

    return {"ok": False, "error": {"message": "Max retries exceeded"}}


def extract_lean_code(response_text):
    if "```lean" in response_text:
        start = response_text.find("```lean") + 6
        end = response_text.find("```", start)
        if end > start:
            return response_text[start:end].strip()
    if "```" in response_text:
        start = response_text.find("```") + 3
        if response_text[start:start + 1] == "\n":
            start += 1
        end = response_text.find("```", start)
        if end > start:
            return response_text[start:end].strip()
    return response_text.strip()


def get_all_zig_files(directory):
    zig_files = []
    for root, dirs, files in os.walk(directory):
        dirs[:] = [
            d for d in dirs if not d.startswith(".") and d != "__zigcache__"
        ]
        for file in files:
            if file.endswith(".zig"):
                zig_files.append(os.path.join(root, file))
    return sorted(zig_files)


async def transpile_file_async(session, zig_file_path, output_base_dir,
                               source_base_dir, api_key, region, model_id,
                               semaphore, counter, total):
    async with semaphore:
        rel_path = os.path.relpath(zig_file_path, source_base_dir)
        lean_rel_path = rel_path[:-3] + ".lean"
        lean_file_path = os.path.join(output_base_dir, lean_rel_path)

        try:
            with open(zig_file_path, "r", encoding="utf-8") as f:
                zig_code = f.read()
        except Exception as e:
            counter[0] += 1
            print(f"[{counter[0]}/{total}] ERROR read {rel_path}")
            return {"ok": False, "file": zig_file_path, "error": str(e)}

        if not zig_code.strip():
            os.makedirs(os.path.dirname(lean_file_path), exist_ok=True)
            with open(lean_file_path, "w", encoding="utf-8") as f:
                f.write("")
            counter[0] += 1
            print(f"[{counter[0]}/{total}] SKIP {rel_path}")
            return {
                "ok": True,
                "file": zig_file_path,
                "lean_file": lean_file_path,
                "skipped": True
            }

        messages = [{"role": "user", "content": zig_code}]

        result = await invoke_bedrock_async(session=session,
                                            messages=messages,
                                            system=TRANSPILE_SYSTEM_PROMPT,
                                            max_tokens=64000,
                                            temperature=0.1,
                                            region=region,
                                            model_id=model_id,
                                            api_key=api_key)

        if not result.get("ok"):
            counter[0] += 1
            print(f"[{counter[0]}/{total}] FAIL {rel_path}")
            return {
                "ok": False,
                "file": zig_file_path,
                "error": result.get("error")
            }

        data = result.get("data")
        lean_code = ""
        if isinstance(data, dict):
            content_value = data.get("content")
            if isinstance(content_value, list):
                parts = []
                for item in content_value:
                    if isinstance(item, dict) and item.get(
                            "type") == "text" and isinstance(
                                item.get("text"), str):
                        parts.append(item["text"])
                lean_code = "".join(parts)
            if not lean_code and isinstance(data.get("raw"), str):
                lean_code = data["raw"]
        else:
            lean_code = str(data)

        lean_code = extract_lean_code(lean_code)

        os.makedirs(os.path.dirname(lean_file_path), exist_ok=True)

        try:
            with open(lean_file_path, "w", encoding="utf-8") as f:
                f.write(lean_code)
        except Exception as e:
            counter[0] += 1
            print(f"[{counter[0]}/{total}] FAIL write {rel_path}")
            return {"ok": False, "file": zig_file_path, "error": str(e)}

        counter[0] += 1
        print(
            f"[{counter[0]}/{total}] OK {lean_rel_path} ({len(lean_code)})")
        return {
            "ok": True,
            "file": zig_file_path,
            "lean_file": lean_file_path,
            "length": len(lean_code)
        }


async def run_transpilation_async():
    api_key = os.environ.get("AWS_BEARER_TOKEN_BEDROCK", "").strip()
    if not api_key:
        print("ERROR: AWS_BEARER_TOKEN_BEDROCK not set")
        return

    region = os.environ.get("AWS_REGION", "us-east-1")
    model_id = os.environ.get(
        "BEDROCK_MODEL_ID", "anthropic.claude-opus-4-6-v1")

    source_dir = os.path.join(os.getcwd(), "fajlok_core")
    output_dir = os.path.join(os.getcwd(), "fajlok_lean")

    if not os.path.isdir(source_dir):
        print("ERROR: fajlok_core not found")
        return

    os.makedirs(output_dir, exist_ok=True)

    zig_files = get_all_zig_files(source_dir)
    total = len(zig_files)

    print(f"Transpiling {total} files (concurrency={CONCURRENCY})...")

    semaphore = asyncio.Semaphore(CONCURRENCY)
    counter = [0]

    connector = aiohttp.TCPConnector(limit=CONCURRENCY * 2,
                                     limit_per_host=CONCURRENCY * 2)
    async with aiohttp.ClientSession(connector=connector) as session:
        tasks = [
            transpile_file_async(session, zig_file, output_dir, source_dir,
                                 api_key, region, model_id, semaphore, counter,
                                 total) for zig_file in zig_files
        ]
        results = await asyncio.gather(*tasks, return_exceptions=True)

    success = sum(1 for r in results if isinstance(r, dict) and r.get("ok"))
    errors = total - success

    print(f"Done! {success} OK, {errors} failed")


if __name__ == "__main__":
    print("fajlok zig→lean Transpiler")
    asyncio.run(run_transpilation_async())

