def sign_aws_request(method: str, service: str, region: str, host: str, 
                    canonical_uri: str, payload: str, access_key: str, 
                    secret_key: str, session_token: Optional[str] = None) -> Dict[str, str]:

    algorithm = 'AWS4-HMAC-SHA256'
    amz_date = datetime.utcnow().strftime('%Y%m%dT%H%M%SZ')
    date_stamp = datetime.utcnow().strftime('%Y%m%d')

    canonical_querystring = ''
    canonical_headers = f'host:{host}\nx-amz-date:{amz_date}\n'
    signed_headers = 'host;x-amz-date'

    if session_token:
        canonical_headers += f'x-amz-security-token:{session_token}\n'
        signed_headers += ';x-amz-security-token'

    payload_hash = hashlib.sha256(payload.encode('utf-8')).hexdigest()
    canonical_request = f'{method}\n{canonical_uri}\n{canonical_querystring}\n{canonical_headers}\n{signed_headers}\n{payload_hash}'

    credential_scope = f'{date_stamp}/{region}/{service}/aws4_request'
    string_to_sign = f'{algorithm}\n{amz_date}\n{credential_scope}\n{hashlib.sha256(canonical_request.encode("utf-8")).hexdigest()}'

    def sign(key: bytes, msg: str) -> bytes:
        return hmac.new(key, msg.encode('utf-8'), hashlib.sha256).digest()

    k_date = sign(('AWS4' + secret_key).encode('utf-8'), date_stamp)
    k_region = sign(k_date, region)
    k_service = sign(k_region, service)
    k_signing = sign(k_service, 'aws4_request')
    signature = hmac.new(k_signing, string_to_sign.encode('utf-8'), hashlib.sha256).hexdigest()

    authorization_header = f'{algorithm} Credential={access_key}/{credential_scope}, SignedHeaders={signed_headers}, Signature={signature}'

    headers = {
        'x-amz-date': amz_date,
        'Authorization': authorization_header
    }

    if session_token:
        headers['x-amz-security-token'] = session_token

    return headers


def normalize_messages(messages: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    if not isinstance(messages, list):
        raise TypeError("messages must be a list")

    normalized = []
    for message in messages:
        if not isinstance(message, dict):
            continue

        role = str(message.get("role", "user")).strip()
        if not role:
            role = "user"

        content = message.get("content", "")

        if isinstance(content, str):
            normalized.append({
                "role": role,
                "content": [{
                    "type": "text",
                    "text": content
                }]
            })
        elif isinstance(content, list):
            parts = []
            for item in content:
                if isinstance(item, dict) and item.get("type") == "text" and isinstance(item.get("text"), str):
                    parts.append({"type": "text", "text": item["text"]})
                elif isinstance(item, str):
                    parts.append({"type": "text", "text": item})

            if not parts:
                parts.append({"type": "text", "text": ""})

            normalized.append({"role": role, "content": parts})
        else:
            normalized.append({
                "role": role,
                "content": [{
                    "type": "text",
                    "text": str(content)[:10000]
                }]
            })

    return normalized


async def invoke_bedrock_async(
    session: aiohttp.ClientSession,
    messages: List[Dict[str, Any]],
    system: Optional[str] = None,
    max_tokens: int = 64000,
    temperature: float = 0.0,
    region: Optional[str] = None,
    model_id: Optional[str] = None,
    access_key: Optional[str] = None,
    secret_key: Optional[str] = None,
    session_token: Optional[str] = None
) -> Dict[str, Any]:

    if not access_key or not secret_key:
        return {
            "ok": False,
            "error": {
                "message": "Missing AWS credentials"
            }
        }

    if not region:
        region = "us-east-1"

    if not model_id:
        model_id = "anthropic.claude-opus-4-6-v1"

    if not region.replace("-", "").replace("_", "").isalnum():
        return {
            "ok": False,
            "error": {
                "message": "Invalid region format"
            }
        }

    if not model_id.replace(".", "").replace("-", "").replace("_", "").isalnum():
        return {
            "ok": False,
            "error": {
                "message": "Invalid model_id format"
            }
        }

    if max_tokens > MAX_TOKENS_LIMIT or max_tokens < 1:
        max_tokens = min(max_tokens, MAX_TOKENS_LIMIT)

    if temperature < 0.0 or temperature > 1.0:
        temperature = max(0.0, min(1.0, temperature))

    host = f"bedrock-runtime.{region}.amazonaws.com"
    canonical_uri = f"/model/{model_id}/invoke"
    url = f""

    body = {
        "anthropic_version": "bedrock-2023-05-31",
        "max_tokens": int(max_tokens),
        "messages": normalize_messages(messages)
    }

    if system and isinstance(system, str) and len(system) > 0:
        body["system"] = system[:50000]

    if temperature is not None:
        body["temperature"] = float(temperature)

    payload = json.dumps(body)

    if len(payload.encode('utf-8')) > MAX_BODY_SIZE:
        return {
            "ok": False,
            "error": {
                "message": f"Request body exceeds {MAX_BODY_SIZE} bytes"
            }
        }

    for attempt in range(MAX_RETRIES):
        try:
            await rate_limiter.acquire(attempt)

            auth_headers = sign_aws_request(
                method='POST',
                service='bedrock',
                region=region,
                host=host,
                canonical_uri=canonical_uri,
                payload=payload,
                access_key=access_key,
                secret_key=secret_key,
                session_token=session_token
            )

            headers = {
                "Content-Type": "application/json",
                "Accept": "application/json",
            }
            headers.update(auth_headers)

            async with session.post(
                url,
                data=payload,
                headers=headers,
                timeout=aiohttp.ClientTimeout(total=REQUEST_TIMEOUT)
            ) as response:

                status = response.status
                content_type = response.headers.get('Content-Type', '')
                raw_bytes = await response.read()

                if status == 429 or "too many requests" in raw_bytes.decode("utf-8", errors="ignore").lower():
                    logger.warning(f"Rate limit hit, attempt {attempt + 1}/{MAX_RETRIES}")
                    continue

                if status >= 500:
                    logger.warning(f"Server error {status}, attempt {attempt + 1}/{MAX_RETRIES}")
                    if attempt < MAX_RETRIES - 1:
                        await asyncio.sleep(BASE_DELAY * (attempt + 1))
                        continue

                if status not in (200, 201, 202):
                    try:
                        error_body = json.loads(raw_bytes.decode("utf-8"))
                    except (json.JSONDecodeError, UnicodeDecodeError):
                        error_body = {
                            "message": raw_bytes.decode("utf-8", errors="ignore")[:1000]
                        }
                    return {
                        "ok": False,
                        "status": status,
                        "error": error_body
                    }

                if 'application/json' not in content_type.lower():
                    logger.warning(f"Unexpected content type: {content_type}")

                try:
                    parsed = json.loads(raw_bytes.decode("utf-8"))
                    return {"ok": True, "data": parsed}
                except (json.JSONDecodeError, UnicodeDecodeError) as e:
                    logger.error(f"JSON decode error: {e}")
                    return {
                        "ok": True,
                        "data": {
                            "raw": raw_bytes.decode("utf-8", errors="ignore")[:10000]
                        }
                    }

        except asyncio.TimeoutError:
            logger.warning(f"Timeout, attempt {attempt + 1}/{MAX_RETRIES}")
            if attempt < MAX_RETRIES - 1:
                await asyncio.sleep(BASE_DELAY * (attempt + 1))
                continue
            return {"ok": False, "error": {"message": "Request timeout"}}

        except aiohttp.ClientError as e:
            logger.warning(f"Client error: {e}, attempt {attempt + 1}/{MAX_RETRIES}")
            if attempt < MAX_RETRIES - 1:
                await asyncio.sleep(BASE_DELAY * (attempt + 1))
                continue
            return {"ok": False, "error": {"message": f"Client error: {str(e)}"}}

        except Exception as e:
            logger.error(f"Unexpected error: {e}, attempt {attempt + 1}/{MAX_RETRIES}")
            if attempt < MAX_RETRIES - 1:
                await asyncio.sleep(BASE_DELAY * (attempt + 1))
                continue
            return {"ok": False, "error": {"message": f"Unexpected error: {str(e)}"}}

    return {"ok": False, "error": {"message": "Max retries exceeded after all attempts"}}


def extract_lean_code(response_text: str) -> str:
    if not isinstance(response_text, str):
        return ""

    markers = ["```lean", "```Lean", "```LEAN"]
    for marker in markers:
        if marker in response_text:
            start = response_text.find(marker) + len(marker)
            if response_text[start:start + 1] == "\n":
                start += 1
            end = response_text.find("```", start)
            if end > start:
                return response_text[start:end].strip()

    if "```" in response_text:
        start = response_text.find("```") + 3
        if start < len(response_text) and response_text[start] == "\n":
            start += 1
        end = response_text.find("```", start)
        if end > start:
            return response_text[start:end].strip()

    return response_text.strip()


def get_all_zig_files(directory: str) -> List[str]:
    if not os.path.isdir(directory):
        raise ValueError(f"Directory does not exist: {directory}")

    if not os.access(directory, os.R_OK):
        raise PermissionError(f"Directory not readable: {directory}")

    zig_files = []

    try:
        for root, dirs, files in os.walk(directory, followlinks=False):
            dirs[:] = [d for d in dirs if not d.startswith(".") and d != "__zigcache__"]

            for file in files:
                if file.lower().endswith(".zig"):
                    full_path = os.path.join(root, file)
                    zig_files.append(full_path)
    except OSError as e:
        logger.error(f"Error walking directory: {e}")
        raise

    return sorted(zig_files)


async def transpile_file_async(
    session: aiohttp.ClientSession,
    zig_file_path: str,
    output_base_dir: str,
    source_base_dir: str,
    access_key: str,
    secret_key: str,
    session_token: Optional[str],
    region: str,
    model_id: str,
    semaphore: asyncio.Semaphore,
    counter: List[int],
    total: int
) -> Dict[str, Any]:

    try:
        async with asyncio.timeout(900):
            async with semaphore:
                rel_path = os.path.relpath(zig_file_path, source_base_dir)
                lean_rel_path = rel_path[:-4] + ".lean" if rel_path.endswith(".zig") else rel_path + ".lean"
                lean_file_path = os.path.join(output_base_dir, lean_rel_path)

                try:
                    with open(zig_file_path, "r", encoding="utf-8") as f:
                        zig_code = f.read()
                except OSError as e:
                    counter += 1
                    logger.error(f"[{counter}/{total}] ERROR reading {rel_path}: {e}")
                    return {"ok": False, "file": zig_file_path, "error": str(e)}
                except UnicodeDecodeError as e:
                    counter += 1
                    logger.error(f"[{counter}/{total}] ERROR decoding {rel_path}: {e}")
                    return {"ok": False, "file": zig_file_path, "error": str(e)}

                if not zig_code or not zig_code.strip():
                    try:
                        os.makedirs(os.path.dirname(lean_file_path), exist_ok=True)
                        with open(lean_file_path, "w", encoding="utf-8") as f:
                            f.write("")
                    except OSError as e:
                        logger.error(f"Error creating empty file {lean_file_path}: {e}")
                        return {"ok": False, "file": zig_file_path, "error": str(e)}

                    counter += 1
                    logger.info(f"[{counter}/{total}] SKIP {rel_path} (empty)")
                    return {
                        "ok": True,
                        "file": zig_file_path,
                        "lean_file": lean_file_path,
                        "skipped": True
                    }

                messages = [{"role": "user", "content": zig_code}]

                result = await invoke_bedrock_async(
                    session=session,
                    messages=messages,
                    system=TRANSPILE_SYSTEM_PROMPT,
                    max_tokens=64000,
                    temperature=0.1,
                    region=region,
                    model_id=model_id,
                    access_key=access_key,
                    secret_key=secret_key,
                    session_token=session_token
                )

                if not result.get("ok"):
                    counter += 1
                    logger.error(f"[{counter}/{total}] FAIL {rel_path}: {result.get('error', {}).get('message', 'Unknown error')}")
                    return {
                        "ok": False,
                        "file": zig_file_path,
                        "error": result.get("error")
                    }

                data = result.get("data", {})
                lean_code = ""

                if isinstance(data, dict):
                    content_value = data.get("content")
                    if isinstance(content_value, list):
                        parts = []
                        for item in content_value:
                            if isinstance(item, dict) and item.get("type") == "text" and isinstance(item.get("text"), str):
                                parts.append(item["text"])
                        lean_code = "".join(parts)

                    if not lean_code and isinstance(data.get("raw"), str):
                        lean_code = data["raw"]
                else:
                    lean_code = str(data)

                lean_code = extract_lean_code(lean_code)

                if not lean_code:
                    counter += 1
                    logger.warning(f"[{counter}/{total}] WARN {rel_path}: Empty response")
                    return {
                        "ok": False,
                        "file": zig_file_path,
                        "error": "Empty Lean code generated"
                    }

                try:
                    os.makedirs(os.path.dirname(lean_file_path), exist_ok=True)
                except OSError as e:
                    counter += 1
                    logger.error(f"[{counter}/{total}] ERROR creating directory for {lean_file_path}: {e}")
                    return {"ok": False, "file": zig_file_path, "error": str(e)}

                try:
                    with open(lean_file_path, "w", encoding="utf-8") as f:
                        f.write(lean_code)
                except OSError as e:
                    counter += 1
                    logger.error(f"[{counter}/{total}] ERROR writing {lean_file_path}: {e}")
                    return {"ok": False, "file": zig_file_path, "error": str(e)}

                counter += 1
                logger.info(f"[{counter}/{total}] OK {lean_rel_path} ({len(lean_code)} bytes)")
                sys.stdout.flush()

                return {
                    "ok": True,
                    "file": zig_file_path,
                    "lean_file": lean_file_path,
                    "length": len(lean_code)
                }

    except asyncio.TimeoutError:
        counter += 1
        logger.error(f"[{counter}/{total}] TIMEOUT {zig_file_path}")
        return {"ok": False, "file": zig_file_path, "error": "File processing timeout"}
    except Exception as e:
        counter += 1
        logger.error(f"[{counter}/{total}] EXCEPTION {zig_file_path}: {e}")
        return {"ok": False, "file": zig_file_path, "error": str(e)}


async def run_transpilation_async() -> int:
    access_key = os.environ.get("AWS_ACCESS_KEY_ID", "").strip()
