            if attempt < MAX_RETRIES - 1:
                await asyncio.sleep(BASE_DELAY * (2 ** attempt))
                continue
            return {"ok": False, "error": {"message": f"Client error: {str(e)}"}}

        except Exception as e:
            logger.error(f"Unexpected error: {e}, attempt {attempt + 1}/{MAX_RETRIES}")
            if attempt < MAX_RETRIES - 1:
                await asyncio.sleep(BASE_DELAY * (2 ** attempt))
                continue
            return {"ok": False, "error": {"message": f"Unexpected error: {str(e)}"}}

    return {"ok": False, "error": {"message": "Max retries exceeded after all attempts"}}


def extract_lean_code(response_text: str) -> str:
    if not isinstance(response_text, str):
        return ""

    markers = ["```lean", "```Lean", "```LEAN"]
    for marker in markers:
        if marker in response_text:
            start = response_text.find(marker) + len(marker)
            if start < len(response_text) and response_text[start] == "\n":
                start += 1
            end = response_text.find("```", start)
            if end > start:
                return response_text[start:end].strip()

    if "```" in response_text:
        start = response_text.find("```") + 3
        if start < len(response_text) and response_text[start] == "\n":
            start += 1
        end = response_text.find("```", start)
        if end > start:
            return response_text[start:end].strip()

    return response_text.strip()


def get_all_zig_files(directory: str) -> List[str]:
    if not os.path.isdir(directory):
        raise ValueError(f"Directory does not exist: {directory}")

    if not os.access(directory, os.R_OK):
        raise PermissionError(f"Directory not readable: {directory}")

    zig_files = []

    try:
        for root, dirs, files in os.walk(directory, followlinks=False):
            dirs[:] = [d for d in dirs if not d.startswith(".") and d != "__zigcache__"]

            for file in files:
                if file.lower().endswith(".zig"):
                    full_path = os.path.join(root, file)
                    zig_files.append(full_path)
    except OSError as e:
        logger.error(f"Error walking directory: {e}")
        raise

    return sorted(zig_files)


async def transpile_file_async(
    session: aiohttp.ClientSession,
    zig_file_path: str,
    output_base_dir: str,
    source_base_dir: str,
    bearer_token: str,
    region: str,
    model_id: str,
    max_tokens: int,
    temperature: float,
    semaphore: asyncio.Semaphore,
    counter: List[int],
    total: int
) -> Dict[str, Any]:

    try:
        async with asyncio.timeout(1800):
            async with semaphore:
                rel_path = os.path.relpath(zig_file_path, source_base_dir)
                lean_rel_path = rel_path[:-4] + ".lean" if rel_path.endswith(".zig") else rel_path + ".lean"
                lean_file_path = os.path.join(output_base_dir, lean_rel_path)

                try:
                    with open(zig_file_path, "r", encoding="utf-8") as f:
                        zig_code = f.read()
                except OSError as e:
                    counter += 1
                    logger.error(f"[{counter}/{total}] ERROR reading {rel_path}: {e}")
                    return {"ok": False, "file": zig_file_path, "error": str(e)}
                except UnicodeDecodeError as e:
                    counter += 1
                    logger.error(f"[{counter}/{total}] ERROR decoding {rel_path}: {e}")
                    return {"ok": False, "file": zig_file_path, "error": str(e)}

                if not zig_code or not zig_code.strip():
                    try:
                        lean_dir = os.path.dirname(lean_file_path)
                        if lean_dir:
                            os.makedirs(lean_dir, exist_ok=True)
                        with open(lean_file_path, "w", encoding="utf-8") as f:
                            f.write("")
                    except OSError as e:
                        logger.error(f"Error creating empty file {lean_file_path}: {e}")
                        return {"ok": False, "file": zig_file_path, "error": str(e)}

                    counter += 1
                    logger.info(f"[{counter}/{total}] SKIP {rel_path} (empty)")
                    return {
                        "ok": True,
                        "file": zig_file_path,
                        "lean_file": lean_file_path,
                        "skipped": True
                    }

                messages = [{"role": "user", "content": zig_code}]

                result = await invoke_bedrock_async(
                    session=session,
                    messages=messages,
                    system=TRANSPILE_SYSTEM_PROMPT,
                    max_tokens=max_tokens,
                    temperature=temperature,
                    region=region,
                    model_id=model_id,
                    bearer_token=bearer_token
                )

                if not result.get("ok"):
                    counter += 1
                    error_msg = result.get('error', {})
                    if isinstance(error_msg, dict):
                        error_msg = error_msg.get('message', 'Unknown error')
                    logger.error(f"[{counter}/{total}] FAIL {rel_path}: {error_msg}")
                    return {
                        "ok": False,
                        "file": zig_file_path,
                        "error": result.get("error")
                    }

                data = result.get("data", {})
                lean_code = ""

                if isinstance(data, dict):
                    content_value = data.get("content")
                    if isinstance(content_value, list):
                        parts = []
                        for item in content_value:
                            if isinstance(item, dict) and item.get("type") == "text" and isinstance(item.get("text"), str):
                                parts.append(item["text"])
                        lean_code = "".join(parts)

                    if not lean_code and isinstance(data.get("raw"), str):
                        lean_code = data["raw"]
                else:
                    lean_code = str(data)

                lean_code = extract_lean_code(lean_code)

                if not lean_code:
                    counter += 1
                    logger.warning(f"[{counter}/{total}] WARN {rel_path}: Empty response")
                    return {
                        "ok": False,
                        "file": zig_file_path,
                        "error": "Empty Lean code generated"
                    }

                try:
                    lean_dir = os.path.dirname(lean_file_path)
                    if lean_dir:
                        os.makedirs(lean_dir, exist_ok=True)
                except OSError as e:
                    counter += 1
                    logger.error(f"[{counter}/{total}] ERROR creating directory for {lean_file_path}: {e}")
                    return {"ok": False, "file": zig_file_path, "error": str(e)}

                try:
                    with open(lean_file_path, "w", encoding="utf-8") as f:
                        f.write(lean_code)
                except OSError as e:
                    counter += 1
                    logger.error(f"[{counter}/{total}] ERROR writing {lean_file_path}: {e}")
                    return {"ok": False, "file": zig_file_path, "error": str(e)}

                counter += 1
                logger.info(f"[{counter}/{total}] OK {lean_rel_path} ({len(lean_code)} bytes)")
                sys.stdout.flush()

                return {
                    "ok": True,
                    "file": zig_file_path,
                    "lean_file": lean_file_path,
                    "length": len(lean_code)
                }

    except asyncio.TimeoutError:
        counter += 1
        logger.error(f"[{counter}/{total}] TIMEOUT {zig_file_path}")
        return {"ok": False, "file": zig_file_path, "error": "File processing timeout"}
    except Exception as e:
        counter += 1
        logger.error(f"[{counter}/{total}] EXCEPTION {zig_file_path}: {e}")
        return {"ok": False, "file": zig_file_path, "error": str(e)}


async def run_transpilation_async() -> int:
    bearer_token = os.environ.get("AWS_BEARER_TOKEN_BEDROCK", "").strip()

    if not bearer_token:
        logger.error("ERROR: AWS_BEARER_TOKEN_BEDROCK environment variable must be set")
        return 1

    region = os.environ.get("AWS_REGION", "us-east-1").strip()
    model_id = os.environ.get("BEDROCK_MODEL_ID", "anthropic.claude-opus-4-6-v1:0").strip()

    try:
        max_tokens = int(os.environ.get("MAX_TOKENS", "64000"))
    except (ValueError, TypeError):
        max_tokens = 64000

    try:
        temperature = float(os.environ.get("TEMPERATURE", "1.0"))
    except (ValueError, TypeError):
        temperature = 1.0

    max_tokens = max(1, min(max_tokens, MAX_TOKENS_LIMIT))
    temperature = max(0.0, min(1.0, temperature))

    source_dir = os.path.join(os.getcwd(), "fajlok_core")
    output_dir = os.path.join(os.getcwd(), "fajlok_lean")

    if not os.path.isdir(source_dir):
        logger.error(f"ERROR: Source directory not found: {source_dir}")
        return 1

    try:
        os.makedirs(output_dir, exist_ok=True)
    except OSError as e:
        logger.error(f"ERROR: Cannot create output directory: {e}")
        return 1

    try:
        zig_files = get_all_zig_files(source_dir)
    except (ValueError, PermissionError, OSError) as e:
        logger.error(f"ERROR: Cannot scan source directory: {e}")
        return 1

    total = len(zig_files)

    if total == 0:
        logger.warning("WARNING: No .zig files found")
        return 0

    logger.info(f"Transpiling {total} files (concurrency={CONCURRENCY}, model={model_id}, max_tokens={max_tokens}, temperature={temperature})...")

    if CONCURRENCY < 1:
        logger.error("ERROR: CONCURRENCY must be positive")
        return 1

    semaphore = asyncio.Semaphore(CONCURRENCY)
    counter = 

    connector = aiohttp.TCPConnector(
        limit=CONCURRENCY * 2,
        limit_per_host=CONCURRENCY,
        ttl_dns_cache=300
    )

    timeout = aiohttp.ClientTimeout(total=None, connect=30, sock_read=REQUEST_TIMEOUT)

    try:
        async with aiohttp.ClientSession(connector=connector, timeout=timeout) as session:
            tasks = [
                transpile_file_async(
                    session, zig_file, output_dir, source_dir,
                    bearer_token, region, model_id, max_tokens, temperature,
                    semaphore, counter, total
                )
                for zig_file in zig_files
            ]
            results = await asyncio.gather(*tasks, return_exceptions=True)
    except Exception as e:
        logger.error(f"ERROR: Session error: {e}")
        return 1

    success = 0
    failed = 0
    exceptions = 0

    for r in results:
        if isinstance(r, Exception):
            exceptions += 1
            logger.error(f"Task exception: {r}")
        elif isinstance(r, dict) and r.get("ok"):
            success += 1
        else:
            failed += 1

    logger.info(f"Done! {success} succeeded, {failed} failed, {exceptions} exceptions")

    return 0 if failed == 0 and exceptions == 0 else 1


def main() -> int:
    try:
        return asyncio.run(run_transpilation_async())
    except KeyboardInterrupt:
        logger.warning("Interrupted by user")
        return 130
    except Exception as e:
        logger.error(f"Fatal error: {e}")
        return 1


if __name__ == "__main__":
    sys.exit(main())
